        processOpsTitle: "Database, Chart & Account",
        processOpsSubtitle: "Candidates archive, organizational chart, and account management",
        processOpsCardTitle: "Database, Chart & Account",
        processOpsDescription:
            "Through the database, you can view all candidates in one place and organize them as a dedicated hiring archive for your company. You can move the strongest candidates to the shortlist, then transfer accepted candidates to the Employees page. From there, you can add them to the organizational chart to build company departments and organize employees in a clear chart that can be reviewed or printed. The Account page also allows you to manage activity, subscriptions, payments, links, account settings, and LinkedIn integration to control the full evaalo experience.",
        privacyPageP1:
            "This Privacy Policy describes how evaalo may collect, use, store, and share personal data when you use our websites and services. It is a template: align it with your jurisdiction, DPA, and subprocessors.",
        privacyPageP2:
            "Typical categories include account and profile data, interview content and metadata, usage logs, and technical identifiers needed for security and service delivery.",
        privacyPageP3:
            "Depending on applicable law, you may have rights to access, rectify, delete, restrict, or object to certain processing. Operational details belong in your Data Processing Agreement and regional addenda.",
        termsPageP1:
            "These Terms of Use govern access to evaalo. By using the service you agree to them. If you disagree, you must not use the product. Replace this text after legal review.",
        termsPageP2:
            "You are responsible for lawful recruiting practices, candidate consent where required, and accurate job and evaluation criteria configured in your account.",
        termsPageP3:
            "Disclaimers, limitation of liability, indemnities, governing law, and dispute resolution should be completed by counsel for your entity and markets.",
        securityPageP1:
            "We implement technical and organizational measures designed to protect customer and candidate data, including access control, encryption in transit, and operational monitoring. Specific controls may vary by deployment.",
        securityPageP2:
            "You should document subprocessors, retention schedules, incident response, and customer responsibilities in your security whitepaper or enterprise agreement.",
        securityPageP3:
            "This page is intentionally high-level so you can attach SOC/ISO summaries, penetration test results, and region-specific compliance statements when available.",
