        aboutPageP1:
            "يوفر evaalo سير عمل للمقابلات وتقييم المرشحين بمساعدة الذكاء الاصطناعي لفرق التوظيف. هذا ملخص مؤقت يمكنك استبداله بقصة شركتكم ورسالتكم والقيادة.",
        aboutPageP2:
            "نركز على تقييمات منظمة وعادلة وقابلة للتوسع عبر الفرز والمقابلات الصوتية والمرئية — مع تقارير واضحة لمسؤولي التوظيف.",
