        whyChoose3Desc: "پێش ئەوەی ناوێک بگاتە خشتەکەت، ایڤالو دوو جار چاوپێکەوتنی لەگەڵ کردووە و ئەوەی دۆزیویەتییەوە نووسیویەتی. کاتەکەت بۆ کاندیدە کۆتاییەکان دەڕوات، نەک بۆ پاڵاوتن.",
        whyChoose4Title: "لیستێکی کورت، نەک خشتەیەک",
        whyChoose4Desc: "کاندیدەکان پاڵ بە پاڵ ڕیزبەندکراون بەپێی ئەو پێوەرانەی خۆت دیاریان دەکەیت. بەراوردەکە تەواو بووە پێش ئەوەی ڕاپۆرتەکە بکەیتەوە.",
