        aboutPageP1:
            "evaalo کاری چاوپێکەوتن و هەڵسەنگاندنی کاندید بە یارمەتی زیرەکی دەستکرد بۆ تیمەکانی دامەزراندن دابین دەکات. ئەمە پێشنووسە — دەتوانیت بە چیرۆکی کۆمپانیا و ئامانج و سەرکردایەتی بگۆڕیت.",
